INSERT INTO public.build_log (data, categoria, titulo, descricao, eh_achado_pesquisa, eh_mapa_inovacao) VALUES ('2026-09-15', 'correcao_bug', 'PR #16 revisado e bug pré-existente em /incidence/search corrigido', 'Revisado o PR #16 (maia-andre): backend/requirements.in + requirements.txt gerados por pip-compile com hashes SHA-256, zerando 14 vulnerabilidades (pip-audit) e atualizando fastapi 0.115→0.141, pydantic 2.9→2.13, uvicorn 0.30→0.53, httpx 0.27→0.28. O PR expôs bug pré-existente: incidence_engine.py atribuía result.scholarships/education/github_projects fora do construtor, o que o Pydantic v2 rejeita ("IncidenceResult object has no field scholarships"). Correção: os três campos foram declarados em IncidenceResult (schemas.py) como Dict com default_factory e passados no construtor em incidence_engine.py:136. Backend compila (compileall). Merge do PR pode prosseguir.', true, true);